def validate():
 j=json.loads((Path(__file__).parent/'mastery_content.json').read_text())
 for course, entries in LESSONS.items():
  assert len(entries)==len(j[course])==10,(course,len(entries))
  for i,row in enumerate(entries):
   assert len(row)==4 and len(row[1].split('|'))==3,(course,i)

if __name__=='__main__':
 validate();print('Valid: 50 tailored teaching expansions')
